---InitAllEquipDojoPlayerCardId
---初始化所有的装备数据的playerCardId
function EquipmentComponent:InitAllEquipDojoAndCoreDojoPlayerCardId()
    ---@type ECSEntity
    local entity = self.entity
    local cardComp = entity:GetComp(ECSComponentType.Constants.CardComponent)
    local cards = cardComp.cards
    local cardCount = table.length(cards)

    if cardCount <= 0 then return end

    local GetEquipIdKeyByPart = EquipUtils.GetEquipIdKeyByPart
    local equipId2CardId = {}
    -- local equipCoreId2CardId = {}
    for i = 1, cardCount do
        ---@type CardDojo
        local cardDojo = cards[i]
        local playerCardId = cardDojo.id
        for part = 1, CardProgressionConstants.EquipmentNum do
            local key = GetEquipIdKeyByPart(part)
            local playerEquipId = checkNumber(cardDojo[key])
            if playerEquipId > 0 then
                equipId2CardId[tostring(playerEquipId)] = playerCardId
            end
        end
        --if checkNumber(cardDojo.equipmentCore) > 0 then
        --    equipCoreId2CardId[tostring(cardDojo.equipmentCore)] = playerCardId
        --end
    end

    table.walk(self.equips, function(_, equipDojo)
        --- checkin equipment 中的 playerCardId 不准 默认初始化为0
        equipDojo.playerCardId = 0
        local playerCardId = equipId2CardId[tostring(equipDojo.id)]
        if playerCardId ~= nil then
            equipDojo.playerCardId = playerCardId
        end
    end)

    --table.walk(self.equipmentCores, function(_, equipmentCoreDojo)
    --    --- checkin equipmentCore 中的 playerCardId 不准 默认初始化为0
    --    equipmentCoreDojo.playerCardId = 0
    --    local playerCardId = equipCoreId2CardId[tostring(equipmentCoreDojo.id)]
    --    if playerCardId ~= nil then
    --        equipmentCoreDojo.playerCardId = playerCardId
    --    end
    --end)
end

