---GetTarotSuitInfo
---获取塔罗牌套装信息 id, partCount
---@param playerCardId number
---@return table table<number,number>
function EquipmentComponent:GetEquipSuitInfo(playerCardId)
    playerCardId = checkNumber(playerCardId)
    local suits = {}
    if playerCardId <= 0 then
        return suits
    end
    ---@type ECSEntity
    local entity = self.entity
    ---@type CardComponent
    local cardComp = entity:GetComp(ECSComponentType.Constants.CardComponent)
    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(playerCardId)
    if not isTable(cardDojo) then
        return suits
    end
    local tarotIds = {}
    for i = 1, Constants.CardEquipmentNo do
        local tarotId = checkNumber(cardDojo[string.format('equipment%s', i)])
        if checkNumber(tarotId) > 0 then
            table.insert(tarotIds, checkNumber(tarotId))
        end
    end
    return self:GetEquipSuitInfoByEquipIdList(tarotIds, 2)
end

---GetEquipSuitInfoByEquipIdList
---根据装备id列表获取塔罗牌套装信息 id, partCount
---@param equipIdList table 装备id列表
---@param minOwnCount number 最小套装散件拥有数量
---@return table table<number,number> <suitId, partCount>
function EquipmentComponent:GetEquipSuitInfoByEquipIdList(equipIdList, minOwnCount)
    local count = 0
    for i, playerEquipId in pairs(equipIdList) do
        if checkNumber(playerEquipId) > 0 then
            count = count + 1
        end
    end
    minOwnCount = minOwnCount or 1
    local suits = {}
    local suitEquipMaxRares = {}
    if count < minOwnCount then
        return suits, suitEquipMaxRares
    end

    ---@type CardConfMgr
    local cardConfMgr = CardConfMgr:GetInstance()
    for _, playerTarotId in pairs(equipIdList) do
        ---@type EquipDojo
        local equipDojo = self:GetEquipById(playerTarotId)
        if not isNull(equipDojo) then
            local vo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
            local suitId = checkNumber(vo.suitId)
            if suitId > 0 then
                if suits[tostring(suitId)] ~= nil then
                    suits[tostring(suitId)] = suits[tostring(suitId)] + 1
                    local oldRare = suitEquipMaxRares[tostring(suitId)]
                    suitEquipMaxRares[tostring(suitId)] = math.max(oldRare, checkNumber(vo.rare))
                else
                    suits[tostring(suitId)] = 1
                    suitEquipMaxRares[tostring(suitId)] = checkNumber(vo.rare)
                end
            end
        end
    end
    return suits, suitEquipMaxRares
end
