---AddCardOnEquip
---给卡牌添加的塔罗牌
---@param playerCardId number
---@param playerEquipId number
---@param equipPart integer
---@return integer
function EquipmentComponent:AddCardOnEquip(playerCardId, playerEquipId, equipPart)
    --- 1.检查要装备的塔罗牌是否被装到其他卡牌身上
    playerEquipId = checkNumber(playerEquipId)
    local oldId
    if playerEquipId > 0 then
        oldId = self:GetCardOnEquipByEquipId(playerEquipId)
        if checkNumber(oldId) > 0 then
            self:RemoveCardOnEquip(oldId, playerEquipId)
        end
    end
    ---@type ECSEntity
    local entity = self.entity
    ---@type CardComponent
    local cardComp = entity:GetComp(ECSComponentType.Constants.CardComponent)
    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(playerCardId)
    if not isTable(cardDojo) then
        return
    end

    local key = string.format("equipment%s", tostring(equipPart))
    --- 2. 检查 要替换 的塔罗牌是否被装到卡牌身上
    local oldTarotId = cardDojo[key]
    if checkNumber(oldTarotId) > 0 then
        oldId = self:GetCardOnEquipByEquipId(oldTarotId)
        if checkNumber(oldId) > 0 then
            self:RemoveCardOnEquip(oldId, oldTarotId)
        end
    end

    cardDojo[key] = playerEquipId
    if playerEquipId > 0 then
        self:GetEquipById(playerEquipId).playerCardId = playerCardId
    end
    return oldTarotId
end

