---AddEquip
---添加塔罗牌 （新加的塔罗牌没有初始化 playerCardId)
---@param equipDojo EquipDojo
function EquipmentComponent:AddEquip(equipDojo)
    if isNull(equipDojo) then
        return
    end
    table.insert(self.equips, equipDojo)
    self._id2dojo[tostring(equipDojo.id)] = equipDojo
end

---RemoveCardOnEquip
---@param playerCardId number
---@param playerEquipId number
function EquipmentComponent:RemoveCardOnEquip(playerCardId, playerEquipId, part)
    ---@type ECSEntity
    local entity = self.entity
    ---@type CardComponent
    local cardComp = entity:GetComp(ECSComponentType.Constants.CardComponent)
    playerEquipId = checkNumber(playerEquipId)
    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(playerCardId)
    if not isTable(cardDojo) then
        return
    end

    local equipDojo = self:GetEquipById(playerEquipId)
    if part == nil then
        ---@type EquipVo
        local equipVo = CardConfMgr:GetInstance():GetEquipVoById(equipDojo.equipmentId)
        part = equipVo.part
    end
    local key = EquipUtils.GetEquipIdKeyByPart(part)
    cardDojo[key] = 0
    equipDojo.playerCardId = 0
end

---交换两张卡牌的装备
---@param playerCardId1 number
---@param playerCardId2 number
function EquipmentComponent:ExchangeEquipmentOfTwoCards(playerCardId1, playerCardId2)
    local cardComp = self.entity:GetComp(ECSComponentType.Constants.CardComponent)
    local cardDojoClone1 = clone(cardComp:GetCardById(playerCardId1))
    local cardDojoClone2 = clone(cardComp:GetCardById(playerCardId2))
    local cardDojo1 = cardComp:GetCardById(playerCardId1)
    local cardDojo2 = cardComp:GetCardById(playerCardId2)
    for i = 1, CardProgressionConstants.EquipmentNum do
        local key = string.format('equipment%d', i)
        cardDojo1[key] = cardDojoClone2[key]
        cardDojo2[key] = cardDojoClone1[key]
        if checkInt(cardDojoClone1[key]) ~= 0 then
            local equipDojo = self:GetEquipById(cardDojoClone1[key])
            equipDojo.playerCardId = playerCardId2
        end
        if checkInt(cardDojoClone2[key]) ~= 0 then
            local equipDojo = self:GetEquipById(cardDojoClone2[key])
            equipDojo.playerCardId = playerCardId1
        end
    end
end

---RemoveEquipsByIdList
---根据传入id列表的移除身上的卡牌
---@param ids table<number, number> <playerEquipId, playerEquipId>
function EquipmentComponent:RemoveEquipsByIdList(ids)
    local idCount = table.count(ids or {})
    if idCount == 0 then return end

    --- 清理 无用数据
    for i, id in pairs(ids) do
        local tempId = checkNumber(id)
        if tempId > 0 then
            self:CheckAndRemoveCardOnEquip(tempId)
            self:RemoveOneEquip(tempId)
        end
    end
end

---CheckAndRemoveCardOnEquip
---检查并且移除在卡牌身上的装备
---@param id number 玩家装备id
function EquipmentComponent:CheckAndRemoveCardOnEquip(id)
    local playerCardId = self:GetCardOnEquipByEquipId(id)
    if checkNumber(playerCardId) > 0 then
        self:RemoveCardOnEquip(playerCardId, id)
    end
end

---RemoveLastOneEquip
---删除最后一个装备
---@param id number    玩家装备id
function EquipmentComponent:RemoveOneEquip(id)
    id = checkNumber(id)
    for i, equipDojo in ipairs(self.equips) do
        if checkNumber(equipDojo.id) == id then
            table.remove(self.equips, i)
            break
        end
    end
     --table.remove(self.equips)
    self._id2dojo[tostring(id)] = nil
end

