---AddEquipCore
---@param equipCoreDojo EquipmentCoreDojo
function EquipmentComponent:AddEquipCore(equipCoreDojo)
    if equipCoreDojo == nil then return end
    table.insert(self.equipmentCores, equipCoreDojo)
    self._coreId2Dojo[tostring(equipCoreDojo.id)] = equipCoreDojo
end


---AddCardOnEquipCore
---给卡牌添加装备核心
---@param playerCardId number
---@param playerEquipCoreId number
function EquipmentComponent:AddCardOnEquipCore(playerCardId, playerEquipCoreId)
    --- 1.检查要装备的装备核心是否被装到其他卡牌身上
    playerEquipCoreId = checkNumber(playerEquipCoreId)
    local oldPlayerCardId
    if playerEquipCoreId > 0 then
        oldPlayerCardId = self:GetCardOnEquipCoreByCoreId(playerEquipCoreId)
        if checkNumber(oldPlayerCardId) > 0 then
            self:RemoveCardOnEquipCore(oldPlayerCardId, playerEquipCoreId)
        end
    end
    ---@type ECSEntity
    local entity = self.entity
    ---@type CardComponent
    local cardComp = entity:GetComp(ECSComponentType.Constants.CardComponent)
    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(playerCardId)
    if not isTable(cardDojo) then
        return
    end

    --- 2. 检查 要替换 的装备核心是否被装到卡牌身上
    local oldEquipCoreId = cardDojo.equipmentCore
    if checkNumber(oldEquipCoreId) > 0 then
        oldPlayerCardId = self:GetCardOnEquipCoreByCoreId(oldEquipCoreId)
        if checkNumber(oldPlayerCardId) > 0 then
            self:RemoveCardOnEquipCore(oldPlayerCardId, oldEquipCoreId)
        end
    end

    cardDojo.equipmentCore = playerEquipCoreId
    if playerEquipCoreId > 0 then
        self:GetEquipCoreById(playerEquipCoreId).playerCardId = playerCardId
    end
    return oldEquipCoreId
end

