    if idCount == 0 then return end

    --- 清理 无用数据
    for i, id in pairs(ids) do
        local tempId = checkNumber(id)
        if tempId > 0 then
            self:CheckAndRemoveCardOnEquipCore(tempId)
            self:RemoveOneEquipCore(tempId)
        end
    end
end

---CheckAndRemoveCardOnEquipCore
