function EquipmentComponent:CheckAndRemoveCardOnEquipCore(id)
    local playerCardId = self:GetCardOnEquipCoreByCoreId(id)
    if checkNumber(playerCardId) > 0 then
        self:RemoveCardOnEquipCore(playerCardId, id)
    end
end

---RemoveCardOnEquipCore
---移除卡牌身上的装备核心
---@param playerCardId number
---@param playerEquipCoreId number
function EquipmentComponent:RemoveCardOnEquipCore(playerCardId, playerEquipCoreId)
    ---@type ECSEntity
    local entity = self.entity
    ---@type CardComponent
    local cardComp = entity:GetComp(ECSComponentType.Constants.CardComponent)
    playerEquipCoreId = checkNumber(playerEquipCoreId)
    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(playerCardId)
    if cardDojo == nil then return end

    ---@type EquipmentCoreDojo
    local equipCoreDojo = self:GetEquipCoreById(playerEquipCoreId)
    cardDojo.equipmentCore     = 0
    equipCoreDojo.playerCardId = 0
end

---RemoveOneEquipCore
---移除一个装备核心数据
---@param id number    玩家装备id
function EquipmentComponent:RemoveOneEquipCore(id)
    id = checkNumber(id)
    for i, equipmentCoreDojo in ipairs(self.equipmentCores) do
        if checkNumber(equipmentCoreDojo.id) == id then
            table.remove(self.equipmentCores, i)
            break
        end
    end
    self._coreId2Dojo[tostring(id)] = nil
end

function EquipmentComponent:GetCardOnEquipCoreByCoreId(coreId)
    return self:GetEquipCoreById(coreId).playerCardId
end

