---@param coreId number
---@return EquipmentCoreDojo
function EquipmentComponent:GetEquipCoreById(coreId)
    return self._coreId2Dojo[tostring(coreId)]
end

---SetLockStateByCoreId
---@param id number    装备核心数据库id
---@param lock number  装备核心解锁状态
function EquipmentComponent:SetLockStateByCoreId(id, lock)
    local equipDojo = self:GetEquipCoreById(id)
    equipDojo.locked = checkNumber(lock)
end

---获得所有装备核心信息
---@return EquipmentCoreDojo[]
function EquipmentComponent:GetAllEquipCores()
    if self.specifyEquipCores then
        return self.specifyEquipCores
    end
    return self.equipmentCores
end

