---GetDiySuits
---获得自定义套装列表
function EquipmentComponent:GetDiySuits()
    return self.diySuits
end

---AddDiySuitBySuitId
---根据套装id添加自定义套装
---@param suitId number
---@param name string
---@param equipments string
function EquipmentComponent:AddDiySuitBySuitId(suitId, name, equipments, playerEquipmentCoreId)
    local diySuits = self.diySuits
    table.insert(diySuits, {
        suitId = suitId, name = name, equipments = equipments, playerEquipmentCoreId = playerEquipmentCoreId
    })
    self:AddEquipId2SuitId(equipments, playerEquipmentCoreId, suitId)
end

---RemoveDiySuitBySuitId
---根据套装id移除自定义套装
---@param suitId number
function EquipmentComponent:RemoveDiySuitBySuitId(suitId)
    local diySuits = self.diySuits
    for i, diySuit in ipairs(diySuits) do
        if checkNumber(diySuit.suitId) == suitId then
            self:RemoveEquipId2SuitId(diySuit.equipments, diySuit.playerEquipmentCoreId, suitId)
            table.remove(diySuits, i)
            break
        end
    end
end

---UpdateDiySuitBySuitId
---根据套装id添加自定义套装
---@param suitId number
---@param name string
---@param equipments string
function EquipmentComponent:UpdateDiySuitBySuitId(suitId, name, equipments, playerEquipmentCoreId)
    local diySuits = self.diySuits
    suitId = checkNumber(suitId)
    for i, v in ipairs(diySuits) do
        if checkNumber(v.suitId) == suitId then
            --- 移除旧的
            local oldEquipments = v.equipments
            self:RemoveEquipId2SuitId(oldEquipments, v.playerEquipmentCoreId, suitId)
            --- 添加新的
            v.suitId = suitId
            v.name = name
            v.equipments = equipments
            v.playerEquipmentCoreId = playerEquipmentCoreId
            self:AddEquipId2SuitId(equipments, playerEquipmentCoreId, suitId)
            break
        end
    end

end

---RemoveInlaidDiySuitEquip
---@param suitId2WaitRemoveEquip table<number, table<number, number>> @ <suitId, <equipId, equipId>>
---@param suitId2WaitRemoveCore table<number, number> @ <suitId, coreId>
function EquipmentComponent:RemoveInlaidDiySuitEquip(suitId2WaitRemoveEquip, suitId2WaitRemoveCore)
    local diySuits = self.diySuits
    local cardTarotNo = Constants.CardEquipmentNo
    for i, diySuit in ipairs(diySuits) do
        local suitId = checkNumber(diySuit.suitId)
        local equipIdMap = suitId2WaitRemoveEquip[suitId]
        if equipIdMap then
            local equipIdList = string.split(diySuit.equipments, ',')
            local idList = {}
            for index = 1, cardTarotNo do
                local equipId = checkInt(equipIdList[index])
                if equipIdMap[equipId] and equipId > 0 then
                    table.insert(idList, 0)
                else
                    table.insert(idList, equipId)
                end
            end
            diySuit.equipments = table.concat(idList, ",")
        end

        if suitId2WaitRemoveCore[suitId] then
            diySuit.playerEquipmentCoreId = 0
        end

    end
end

---InitEquipId2SuitId
---warn 一个装备可能会有多个套装的情况
function EquipmentComponent:InitEquipId2SuitIdMap()
    if self.equipId2SuitIdMap and self.coreId2SuitIdMap then
        return self.equipId2SuitIdMap, self.coreId2SuitIdMap
    end
    local equipId2SuitIdMap = {}
    local coreId2SuitIdMap  = {}
    local diySuits = self.diySuits
    for i, diySuit in ipairs(diySuits) do
        local suitId = diySuit.suitId
        local equipIdList = string.split(diySuit.equipments, ',')
        for _, equipId in pairs(equipIdList) do
            if checkNumber(equipId) > 0 then
                equipId2SuitIdMap[tostring(equipId)] = equipId2SuitIdMap[tostring(equipId)] or {}
                equipId2SuitIdMap[tostring(equipId)][tostring(suitId)] = suitId
            end
        end

        local playerEquipmentCoreId = checkNumber(diySuit.playerEquipmentCoreId)
        if playerEquipmentCoreId > 0 then
            coreId2SuitIdMap[tostring(playerEquipmentCoreId)] = coreId2SuitIdMap[tostring(playerEquipmentCoreId)] or {}
            coreId2SuitIdMap[tostring(playerEquipmentCoreId)][tostring(suitId)] = suitId
        end
    end
    self.equipId2SuitIdMap = equipId2SuitIdMap
    self.coreId2SuitIdMap = coreId2SuitIdMap
    return equipId2SuitIdMap, coreId2SuitIdMap
end

---AddEquipId2SuitId
---添加id2SuitId
---@param equipments string 装备id字符串（id,id,id,id,id,id）
---@param suitId number
function EquipmentComponent:AddEquipId2SuitId(equipments, playerEquipmentCoreId, suitId)
    local equipIdList = string.split(equipments, ',')
    local id2SuitIdMap, coreId2SuitIdMap = self:GetId2SuitIdMap()
    for _, equipId in pairs(equipIdList) do
        id2SuitIdMap[tostring(equipId)] = id2SuitIdMap[tostring(equipId)] or {}
        id2SuitIdMap[tostring(equipId)][tostring(suitId)] = suitId
    end

    if checkNumber(playerEquipmentCoreId) > 0 then
        coreId2SuitIdMap[tostring(playerEquipmentCoreId)] = coreId2SuitIdMap[tostring(playerEquipmentCoreId)] or {}
        coreId2SuitIdMap[tostring(playerEquipmentCoreId)][tostring(suitId)] = suitId
    end
end

---RemoveEquipId2SuitId
---添加id2SuitId
---@param equipments string 装备id字符串（id,id,id,id,id,id）
---@param suitId number
function EquipmentComponent:RemoveEquipId2SuitId(equipments, playerEquipmentCoreId, suitId)
    local equipIdList = string.split(equipments, ',')
    local id2SuitIdMap, coreId2SuitIdMap = self:GetId2SuitIdMap()
    for _, equipId in pairs(equipIdList) do
        if id2SuitIdMap[tostring(equipId)] then
            id2SuitIdMap[tostring(equipId)][tostring(suitId)] = nil
        end
    end

    if checkNumber(playerEquipmentCoreId) > 0 and coreId2SuitIdMap[tostring(playerEquipmentCoreId)] then
        coreId2SuitIdMap[tostring(playerEquipmentCoreId)][tostring(suitId)] = nil
    end

end

---CheckEquipOnDiySuit
---检查装备是否在自定义套装中
---@param equipId number
function EquipmentComponent:CheckEquipOnDiySuit(equipId)
    local id2SuitIdMap = self:GetId2SuitIdMap()
    local suitIdMap = id2SuitIdMap[tostring(equipId)]
    return suitIdMap ~= nil and next(suitIdMap) ~= nil
end

---CheckEquipCoreOnDiySuit
---检查装备核心是否在自定义套装中
---@param coreId number
function EquipmentComponent:CheckEquipCoreOnDiySuit(coreId)
    local _, coreId2SuitIdMap = self:GetId2SuitIdMap()
    local suitIdMap = coreId2SuitIdMap[tostring(coreId)]
    return suitIdMap ~= nil and next(suitIdMap) ~= nil
end

function EquipmentComponent:GetId2SuitIdMap()
    return self:InitEquipId2SuitIdMap()
end

function EquipmentComponent:GetDiySuitDataBySuitId(suitId)
    local diySuits = self:GetDiySuits()
    suitId = checkNumber(suitId)
    for i, v in ipairs(diySuits) do
        if checkNumber(v.suitId) == suitId then
            return v
        end
    end
end

