--------------------------------------------

function EquipmentComponent:InitOwnEquipSuitIds()
    local ownEquipSuitIds = {}

    local cardConfMgr = CardConfMgr:GetInstance()
    local equips          = self:GetAllEquips()
    local equipId2EquipInfo  = {}
    ---@param equipDojo EquipDojo
    for _, equipDojo in ipairs(equips) do
        local suitId, part
        local refId = tostring(equipDojo.equipmentId)
        local info = equipId2EquipInfo[refId]
        if info == nil then
            ---@type EquipVo
            local equipVo = cardConfMgr:GetEquipVoById(refId)
            suitId = equipVo.suitId
            part = equipVo.part
            equipId2EquipInfo[refId] = {suitId, part}
        else
            suitId, part = SafeUnpack(info)
        end
        if suitId > 0 then
            ownEquipSuitIds[suitId] = ownEquipSuitIds[suitId] or {}
            ownEquipSuitIds[suitId][part] = ownEquipSuitIds[suitId][part] or {}
            table.insert(ownEquipSuitIds[suitId][part], equipDojo.id)
        end
    end
    return ownEquipSuitIds
end

function EquipmentComponent:AddSpecifyEquipBackpack(str)
    local equipAndCoreList = parse_strings(str, ":")
    local coreGoodsId       = 0
    local equipGoodsId2flag = {}
    local equipGoodsIdCount = 0
    local count = #equipAndCoreList
    for i = 1, count do
        local goodsId = checkNumber(equipAndCoreList[i])
        if goodsId > 0 then
            if i == count then
                coreGoodsId = goodsId
            else
                equipGoodsId2flag[goodsId] = true
                equipGoodsIdCount = equipGoodsIdCount + 1
            end
        end
    end

    local specifyEquips = {}
    --local specifyId2dojo = {}
    local equips = self:GetAllEquips()
    for index, equipDojo in ipairs(equips) do
        local equipmentId = checkNumber(equipDojo.equipmentId)
        if equipGoodsId2flag[equipmentId] then
            table.insert(specifyEquips, equipDojo)

            equipGoodsId2flag[equipmentId] = false
            equipGoodsIdCount = equipGoodsIdCount - 1
            if equipGoodsIdCount == 0 then break end
        end        
    end
    if next(specifyEquips) then
         self.specifyEquips = specifyEquips
