---计算装备评分
---@param equipDojo EquipDojo 
function EquipmentComponent:CalculateEvaluateScore(equipDojo)
    local startStar =  EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.StartStar)
    local score = self:CalculateMainAttrEvaluateScore(equipDojo)
    local equipVo = CardConfMgr:GetInstance():GetEquipVoById(equipDojo.equipmentId)
    for i = 1, math.min(startStar - 1, checkInt(equipDojo.star)), 1 do
        local attrId  = equipDojo[string.format('attr%dId', i)]
        local num  = equipDojo[string.format('attr%dNum', i)]
        local quality  = equipDojo[string.format('attr%dQuality', i)]
        score = score + self:CalculateSubAttrEvaluateScore(equipVo, attrId, num, quality)
    end
    
    if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id118) then
        local ladderRiseAttrs = equipDojo:GetLadderRiseAttrs()
        for index, attr in pairs(ladderRiseAttrs) do
            score = score + self:CalculateLadderAttrEvaluateScore(index, equipVo, attr)
        end
    end

    return score
end

---计算主属性装备评分
---@param equipDojo EquipDojo
function EquipmentComponent:CalculateMainAttrEvaluateScore(equipDojo)
    if not self._mainScoreConf then
        self._mainScoreConf = self:GetEquipmentScoreConf(CardProgressionConstants.EquipmentScoreConfigType.MaiAttr)
    end
    local equipVo = CardConfMgr:GetInstance():GetEquipVoById(equipDojo.equipmentId)
    local startStar =  EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.StartStar)
    local conf = self._mainScoreConf[EquipUtils.GetQuality(equipDojo)] or self._mainScoreConf[equipVo.rare]
    local score = checkInt(conf.para2[1])
    local star = checkInt(equipDojo.star)
    local offset = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id118) and 0 or -1
    local normalStar = math.min(startStar + offset, star)
    for i = 0, normalStar do
        if i == startStar then
            score = score + checkInt(conf.para3[i + 1])
        elseif star > i then
            score = score + checkInt(conf.para3[i + 1]) * 5
        else
            score = score + checkInt(conf.para3[i + 1]) * checkInt(equipDojo.level)
        end
    end
    return score
end

---计算副属性评分
---@param equipVo EquipVo @ 装备配表数据
---@param attrId integer @ 属性Id
---@param attrNum integer @ 属性数值
---@param quality integer @ 属性品质
function EquipmentComponent:CalculateSubAttrEvaluateScore(equipVo, attrId, attrNum, quality)
    if (not self._subAttrScoreConf) or (not self._subAttrRareScoreConf)  then
        self._subAttrScoreConf = self:GetEquipmentScoreConf(CardProgressionConstants.EquipmentScoreConfigType.SubAttr)
        self._subAttrRareScoreConf = self:GetEquipmentScoreConf(CardProgressionConstants.EquipmentScoreConfigType.SubAttrRare)
    end

    local attrConf = self._subAttrScoreConf[checkNumber(attrId)]
    local rareConf = self._subAttrRareScoreConf[checkNumber(quality)]
    local percent = EquipUtils.GetSubAttrPercent(equipVo.equipId, attrId, attrNum)
    return self:CalculateAttrEvaluateScore(rareConf, equipVo, attrConf, percent)
end

---@param index number
---@param equipVo EquipVo
---@param attr LadderRiseAttr
---@return number
function EquipmentComponent:CalculateLadderAttrEvaluateScore(index, equipVo, attr)
    if not attr.isUnlock then return 0 end
    if self._ladderAttr1EvaluateScoreConf == nil or self._ladderAttr1RareEvaluateScoreConf == nil or self._ladderAttr2EvaluateScoreConf == nil or self._ladderAttr2RareEvaluateScoreConf == nil  then
        self._ladderAttr1EvaluateScoreConf = self:GetEquipmentScoreConf(CardProgressionConstants.EquipmentScoreConfigType.LadderRiseAttr1)
        self._ladderAttr1RareEvaluateScoreConf = self:GetEquipmentScoreConf(CardProgressionConstants.EquipmentScoreConfigType.LadderRiseAttr1Rare)
        self._ladderAttr2EvaluateScoreConf = self:GetEquipmentScoreConf(CardProgressionConstants.EquipmentScoreConfigType.LadderRiseAttr2)
        self._ladderAttr2RareEvaluateScoreConf = self:GetEquipmentScoreConf(CardProgressionConstants.EquipmentScoreConfigType.LadderRiseAttr2Rare)
    end
    
    local attrId, attrNum, percent, quality = attr.attrId, attr.num, attr.attrProgress, attr.quality
    local scoreConf = index == 1 and self._ladderAttr1EvaluateScoreConf[attrId] or self._ladderAttr2EvaluateScoreConf[attrId]
    local rareConf = index == 1 and self._ladderAttr1RareEvaluateScoreConf[quality] or self._ladderAttr2RareEvaluateScoreConf[quality]

    local score = checkInt(rareConf.para2[1]) + checkInt(scoreConf.para2[1] * percent)
    return score
end

function EquipmentComponent:CalculateAttrEvaluateScore(rareConf, equipVo, attrConf, percent)
    if rareConf == nil then
        return 0
    end
    local score = checkInt(rareConf.para2[1])
    for i, v in ipairs(checkTable(attrConf.para2)) do
        if checkInt(v) == equipVo.suitId then
            score = score + checkInt(tonumber(attrConf.para3[i]) * percent * 100)
            break
        end
    end
    return score
end

---获取装备评分配置
---@param type CardProgressionConstants.EquipmentScoreConfigType
function EquipmentComponent:GetEquipmentScoreConf(type)
    local mainConf = CfUtils.GetCf(AutoIds.IdSetting6123, "EquipmentScoreVo", true)
    local conf = {}
    for _, v in ipairs(mainConf) do
        if checkInt(v.effect) == type then
            conf[checkNumber(v.para1)] = v
        end
    end
    return conf
end

return EquipmentComponent